n.exploreUrl:
@js:
var arr = [];
arr.push({title: '🎵 推荐歌单', url: 'https://fy-musicbox-api.mu-jie.cc/netease/playlist/recommend?limit=30', style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}});
var body = java.ajax('https://fy-musicbox-api.mu-jie.cc/getPlaylistCategory,{"headers":{"Referer":"https://mu-jie.cc/"}}')   // 请求分类树
var d = JSON.parse(body);
var cats = (d && d[0] && d[0].category) || [];
for (var i = 0; i < cats.length; i++) {
  var g = cats[i];
  var subs = g.sub || [];
  if (subs.length > 0) {
    arr.push({title: g.name, url: '', style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}});   // 分组标题独占一行
    for (var j = 0; j < subs.length; j++) {
      var s = subs[j];
      arr.push({title: s.name, url: 'https://fy-musicbox-api.mu-jie.cc/netease/playlist/category?type=' + encodeURIComponent(s.id) + '&limit=30', style: {layout_flexGrow: 1, layout_flexBasisPercent: 0.25}});
    }
  }
}
JSON.stringify(arr);

