A = () => {
    let v = String(this.source.getVariable()).split(',');
    let x = parseInt(v[0]) || 0;
    let names = ['歌曲', '歌单'];
    let icons = ['🎵', '📋'];
    let nl = String.fromCharCode(10);
    java.toast('━━━━━━━━━━━' + nl +
        icons[x] + ' 当前搜索模式' + nl +
        names[x] + nl +
        '━━━━━━━━━━━');
};
B = (x) => {
    let v = String(this.source.getVariable()).split(',');
    v[0] = x;
    this.source.setVariable(v.join(','));
    let names = ['歌曲', '歌单'];
    java.toast('已切换到：' + names[x]);
};

